INSERT INTO duas (id, category, badge, title, short_desc, arabic, translit, translation) VALUES
('ease-in-affairs', 'Ease', 'DAILY FEATURED DUA', 'Dua for ease in affairs', 'Recite when facing difficulties.', 'اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا', 'Allahumma la sahla illa ma ja''altahu sahla, wa Anta taj''alul-hazna idha shi''ta sahla.', '"O Allah, there is no ease except in that which You have made easy, and You make the difficulty, if You wish, easy." (Ibn Hibban)'),
('anxious-heart', 'Peace', 'PROPHETIC REFUGE', 'Dua for anxiety & sorrow', 'Calm a restless heart with reliance on Allah.', 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', 'HasbunAllahu wa ni''mal wakeel.', '"Sufficient for us is Allah, and [He is] the best Disposer of affairs." (Quran 3:173)'),
('thursday-salawat', 'Gratitude', 'THURSDAY NIGHT SUNNAH', 'Salawat Ibrahimiyyah (6x)', 'Send abundant blessings upon the Prophet ﷺ.', 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ', 'Allahumma salli ''ala Muhammadin wa ''ala aali Muhammad.', '"O Allah, send Your grace, honour and mercy upon Muhammad and upon the family of Muhammad."')
